// Call and validate the returned static string pointer
auto ver = nc_inq_libvers();
FUZZ_ASSERT(ver != nullptr, "nc_inq_libvers must return non-null static string");
// Do not free or modify ver (static storage).

// Provide an arbitrary error code; netCDF accepts NC_* negatives or errno values
int ncerr = (int)(*FUZZ_PARAM(int));
const char* msg = nc_strerror(ncerr);
// The API returns a static string (may describe unknown code). Do not free/modify.
FUZZ_ASSERT(msg != nullptr, "nc_strerror must return non-null static string");

// mode_flag must use a user-defined format bit. We synthesize a high bit-pattern to
// avoid colliding with common NC_* flags, but allow variability for coverage.
int mode_flag = 0x10000000 | (int)(*FUZZ_PARAM(unsigned int) & 0x0FFF);
// magic number must be <= 8 bytes; ensure NUL termination for safety
std::string magic_src = FUZZ_PARAM_STR();
char magic_number[9];
size_t mlen = magic_src.size();
if (mlen > 8) mlen = 8;
for (size_t i = 0; i < mlen; ++i) magic_number[i] = magic_src[i];
magic_number[mlen] = '\0';
// dispatch_table must point to a valid NC_Dispatch provided by fuzzer runtime.
// Invoke registration; record the mode flag globally for inquiry pairing.
int ret = nc_def_user_format(mode_flag, dispatch_table, magic_number);
FUZZ_SET_ATTR_INT_GLOBAL("udf_mode_flag", mode_flag);
// Even if registration fails, we return dispatch_table as output (ownership unchanged).

// Query a previously registered user-defined format. Use the globally stored flag
// if available, otherwise a random synthesized one.
int mode_flag = FUZZ_GET_ATTR_INT_GLOBAL("udf_mode_flag");
if (mode_flag == 0) {
    mode_flag = 0x10000000 | (int)(*FUZZ_PARAM(unsigned int) & 0x0FFF);
}
NC_Dispatch* out_tbl = nullptr;
char magic_number[16]; // >= 9 ensures room for up to 8-byte magic + NUL
(void)nc_inq_user_format(mode_flag, &out_tbl, magic_number);
// No persistence required; do not free or store out_tbl; magic_number is caller-provided buffer.

// Non-negative values; keep within a small range for performance
int threshold = (int)(*FUZZ_PARAM(unsigned int) % 1024);
int alignment = (int)(*FUZZ_PARAM(unsigned int) % 1024);
(void)nc_set_alignment(threshold, alignment);
// This affects global defaults for future file creations.

// Retrieve alignment; exercise NULL handling by optionally skipping one
int t = 0, a = 0;
int use_t = (int)(*FUZZ_PARAM(unsigned int) & 1);
int use_a = (int)(*FUZZ_PARAM(unsigned int) & 1);
size_t* dummy = nullptr; // no use, just to avoid unused warnings in some compilers
(void)dummy; // silence
(void)nc_get_alignment(use_t ? &t : nullptr, use_a ? &a : nullptr);
// No further assertions; API may return current settings.

// Create a new dataset with tuning parameters
const char* path = FUZZ_PARAM_FILENAME();
int cmode = NC_CLOBBER | ((int)(*FUZZ_PARAM(unsigned int) & 1) ? NC_NETCDF4 : 0);
size_t initialsz = (size_t)(*FUZZ_PARAM(unsigned int) % 1024);
size_t chunk_hint = (size_t)(*FUZZ_PARAM(unsigned int) % 2048);
size_t* chunkp = ((int)(*FUZZ_PARAM(unsigned int) & 1)) ? &chunk_hint : nullptr;
int ncid = -1;
int r = nc__create(path, cmode, initialsz, chunkp, &ncid);
if (r == 0) { (void)nc_close(ncid); }
// We close on success to avoid leaking open FDs.

