size_t elem_bytes = 4u * (size_t)dimsizes[0]*(size_t)dimsizes[1]*(size_t)dimsizes[2];
size_t off = (elem_bytes <= csize) ? (csize - elem_bytes) : 0; (void)nc_insert_array_compound(ncid, ctid, "a", off, NC_INT, ndims, dimsizes);
